; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPC (NTCCPC.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_goto_ifzero_n:	jp 15
kw_next1l_n:	jp 31
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_ztov:		jp 49
kw_ftov:		jp 50
kw_sublv:	jp 56
kw_mulvl:	jp 61
kw_orvv:		jp 74
kw_cpeqvl:	jp 96
kw_cpnevv:	jp 97
kw_cpnevl:	jp 98
kw_aset:		jp 112
kw_strcpy:	jp 122
kw_printzoscii:	jp 129
kw_printstrvar:	jp 130
kw_printint:	jp 132
kw_printnl:	jp 139
kw_inkey:	jp 145
kw_scrinit:	jp 147
kw_model:	jp 151
kw_frame:	jp 153
kw_ticks:	jp 155
kw_bssinit:	jp 283
ntc_plat_irqon:	jp 308
NTC_RJ_N	equ 28		; entries
ntc_csp	equ #8800		; ROM data
ntc_font	equ #948E		; ROM bss
ntc_nmode	equ #8807		; ROM data
ntc_v_free	equ #88C1		; ROM data
ntc_v_romen	equ #88C7		; ROM data
ntc_v_romold	equ #88C9		; ROM data
ntc_v_stamp	equ #88C5		; ROM data
ntc_v_start	equ #88C3		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM in slots 0 - 31, have it patch the jump block. NC = ready;
; C = not there / too old (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, c				; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot; C: DE = a number it hasn't got
			jr c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld hl, ntc_rj_tlk
			or a
			sbc hl, de			; (DE: past the message shown)
			jr nz, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_sig:		db "NTC", 1, "CPC", 0	; the ROM's NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPC (NTCCPC.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPC too old: no routine #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
arr_a		equ ntc_bss + 0		; 20 bytes
arr_b		equ ntc_bss + 20		; 20 bytes
ntc_bss_size	equ 40
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "AMSDOS.BIN", ntc_start, ntc_end - ntc_start, ntc_start
